SYSTEM_PROMPT = "You are a movie recommendation agent."
TAU_REC_TOOLS = [
    "search_catalog",
    "get_metadata",
    "check_availability",
    "get_user_history",
    "check_content_preference",
    "recommend",
]


class Recorder:
    """A mockllm custom_outputs callable that records every generate call."""

    def __init__(self, outputs: list[ModelOutput]):
        self._outputs = list(outputs)
        self.calls: list[dict] = []

    def __call__(self, input, tools, tool_choice, config):
        self.calls.append(
            {"input": list(input), "tools": list(tools), "config": config}
        )
        return self._outputs.pop(0)


def _model(recorder: Recorder, name: str = "mockllm/model", **kwargs):
    return get_model(name, custom_outputs=recorder, memoize=False, **kwargs)


def _agent(model) -> InspectAgent:
    return InspectAgent(model, SYSTEM_PROMPT, TOOL_DEFINITIONS)


@contextmanager
def active(model, config: GenerateConfig = GenerateConfig()):
    """Make ``model`` Inspect's active model, as it is inside a sample."""
    model_token = active_model_context_var.set(model)
    config_token = active_generate_config_context_var.set(config)
    try:
        yield
    finally:
        active_generate_config_context_var.reset(config_token)
        active_model_context_var.reset(model_token)


def _tool_output(calls: list[tuple[str, str, dict]], content: str = "") -> ModelOutput:
    output = ModelOutput.for_tool_call(
        "mockllm/model", calls[0][1], calls[0][2], tool_call_id=calls[0][0], content=content
    )
    output.choices[0].message.tool_calls = [
        ToolCall(id=call_id, function=name, arguments=args)
        for call_id, name, args in calls
    ]
    return output


async def test_agent_generations_use_active_model():
    recorder = Recorder([ModelOutput.from_content("mockllm/model", "Hello!")])
    model = _model(recorder)
    agent = _agent(model)
    agent.add_assistant_message("Hi, what are you in the mood for?")
    agent.add_user_message("Something funny.")
    with active(model):
        response = await agent.respond(None)

    assert isinstance(response, AgentResponse)
    assert response.message == "Hello!"
    assert response.tool_calls == []
    assert len(recorder.calls) == 1
    sent = recorder.calls[0]["input"]
    assert isinstance(sent[0], ChatMessageSystem)
    assert sent[0].text == SYSTEM_PROMPT
    assert [m.role for m in sent] == ["system", "assistant", "user"]
    assert [m.text for m in sent[1:]] == [
        "Hi, what are you in the mood for?", "Something funny.",
    ]
    assert [tool.name for tool in recorder.calls[0]["tools"]] == TAU_REC_TOOLS


async def test_tool_results_appended_as_tool_messages():
    recorder = Recorder([
        _tool_output([("c1", "search_catalog", {"query": "comedy"})]),
        ModelOutput.from_content("mockllm/model", "Found one."),
    ])
    model = _model(recorder)
    agent = _agent(model)
    agent.add_user_message("Something funny.")
    with active(model):
        first = await agent.respond(None)
        assert first.tool_calls == [
            {"id": "c1", "name": "search_catalog", "arguments": {"query": "comedy"}}
        ]
        await agent.respond(tool_results=[{"role": "tool", "tool_call_id": "c1", "content": "x"}])

    second_input = recorder.calls[1]["input"]
    assert [m.role for m in second_input] == ["system", "user", "assistant", "tool"]
    # The assistant turn is kept as returned (tool calls included).
    assert second_input[2].tool_calls[0].id == "c1"
    tool_message = second_input[-1]
    assert isinstance(tool_message, ChatMessageTool)
    assert tool_message.tool_call_id == "c1"
    assert tool_message.text == "x"
    assert tool_message.function == "search_catalog"


async def test_text_and_tool_calls_same_turn():
    recorder = Recorder([
        _tool_output(
            [("c1", "get_metadata", {"item_id": "m1"})], content="Let me check that one."
        )
    ])
    model = _model(recorder)
    agent = _agent(model)
    agent.add_user_message("Tell me about m1.")
    with active(model):
        response = await agent.respond(None)

    assert response.message == "Let me check that one."
    assert response.tool_calls == [
        {"id": "c1", "name": "get_metadata", "arguments": {"item_id": "m1"}}
    ]


async def test_multiple_tool_calls_order_preserved():
    calls = [
        ("c1", "get_user_history", {"user_id": "u1"}),
        ("c2", "search_catalog", {"query": "space"}),
        ("c3", "check_availability", {"item_id": "m9", "services": ["netflix"]}),
    ]
    recorder = Recorder([_tool_output(calls)])
    model = _model(recorder)
    agent = _agent(model)
    agent.add_user_message("Sci-fi please.")
    with active(model):
        response = await agent.respond(None)

    assert response.message is None
    assert response.tool_calls == [
        {"id": call_id, "name": name, "arguments": args} for call_id, name, args in calls
    ]


@pytest.mark.parametrize("item_id", [None, "null", "None"])
async def test_recommend_null_arguments_unchanged(item_id):
    recorder = Recorder([_tool_output([("c1", "recommend", {"item_id": item_id})])])
    model = _model(recorder)
    agent = _agent(model)
    agent.add_user_message("Nothing fits, right?")
    with active(model):
        response = await agent.respond(None)

    assert response.tool_calls[0]["arguments"] == {"item_id": item_id}
    assert type(response.tool_calls[0]["arguments"]["item_id"]) is type(item_id)


async def test_model_length_raises_context_length():
    recorder = Recorder([
        ModelOutput.from_content("mockllm/model", "", stop_reason="model_length")
    ])
    model = _model(recorder)
    agent = _agent(model)
    agent.add_user_message("Hi.")
    with active(model), pytest.raises(AgentContextLengthError) as info:
        await agent.respond(None)
    message = str(info.value).lower()
    assert "context length" in message
    # The legacy orchestrator's context-stop test.
    assert "context" in message and "length" in message


async def test_content_filter_raises():
    recorder = Recorder([
        ModelOutput.from_content("mockllm/model", "I can't help.", stop_reason="content_filter")
    ])
    model = _model(recorder)
    agent = _agent(model)
    agent.add_user_message("Hi.")
