async def test_mirrored_settings_fill_only_unset():
    # Native sends temperature 0.0 for a model that accepts it.
    recorder = Recorder([ModelOutput.from_content("mockllm/model", "ok")])
    model = _model(recorder)
    agent = _agent(model)
    agent.add_user_message("Hi.")
    with active(model):
        await agent.respond(None)
    assert recorder.calls[0]["config"].temperature == 0.0

    # An explicit (active) temperature wins.
    recorder = Recorder([ModelOutput.from_content("mockllm/model", "ok")])
    model = _model(recorder)
    agent = _agent(model)
    agent.add_user_message("Hi.")
    with active(model, GenerateConfig(temperature=0.7)):
        await agent.respond(None)
    assert recorder.calls[0]["config"].temperature == 0.7


async def test_model_config_temperature_is_explicit():
    recorder = Recorder([ModelOutput.from_content("mockllm/model", "ok")])
    model = _model(recorder, config=GenerateConfig(temperature=0.4))
    agent = _agent(model)
    agent.add_user_message("Hi.")
    with active(model):
        await agent.respond(None)
    assert recorder.calls[0]["config"].temperature == 0.4


async def test_settings_use_provider_qualified_name(monkeypatch):
    seen = []
    import tau_rec.inspect_support.agent as agent_module

    def fake_settings(model, reasoning_effort, harness):
        seen.append((model, reasoning_effort))
        return {}

    monkeypatch.setattr(agent_module, "agent_request_settings", fake_settings)
    recorder = Recorder([ModelOutput.from_content("mockllm/model", "ok")])
    model = _model(recorder)
    agent = _agent(model)
    agent.add_user_message("Hi.")
    with active(model, GenerateConfig(reasoning_effort="low")):
        await agent.respond(None)
    # Not `model.name` ("model"): the provider prefix reaches native_model_name.
    assert seen == [("mockllm/model", "low")]


async def test_reset_clears_history():
    recorder = Recorder([
        ModelOutput.from_content("mockllm/model", "one"),
        ModelOutput.from_content("mockllm/model", "two"),
    ])
    model = _model(recorder)
    agent = _agent(model)
    agent.add_user_message("Hi.")
    with active(model):
        await agent.respond(None)
        agent.reset()
        agent.add_user_message("Again.")
        await agent.respond(None)
    assert [m.role for m in recorder.calls[1]["input"]] == ["system", "user"]


def test_tool_infos_drop_additional_properties():
    infos = tool_infos(TOOL_DEFINITIONS)
    assert [info.name for info in infos] == TAU_REC_TOOLS
    for info, definition in zip(infos, TOOL_DEFINITIONS):
        function = definition["function"]
        assert info.description == function["description"]
        assert info.parameters.additionalProperties is None
        dumped = info.parameters.model_dump(exclude_none=True)
        assert dumped == function["parameters"]


# fill_unset ---------------------------------------------------------------


def test_fill_unset_takes_only_unset_fields():
    config = fill_unset(
        {"temperature": 0.0, "max_tokens": 32_768},
        GenerateConfig(temperature=0.7),
    )
    assert config.temperature == 0.7
    assert config.max_tokens == 32_768


def test_fill_unset_folds_thinking_into_extra_body():
    mirrored = {
        "temperature": 0.0,
        "thinking": {"type": "disabled"},
        "extra_body": {"thinking": {"type": "disabled"}},
    }
    config = fill_unset(mirrored, GenerateConfig())
    assert config.extra_body == {"thinking": {"type": "disabled"}}
    assert config.temperature == 0.0


def test_fill_unset_explicit_extra_body_keys_win():
    config = fill_unset(
        {"extra_body": {"thinking": {"type": "disabled"}, "reasoning": {"effort": "low"}}},
        GenerateConfig(extra_body={"thinking": {"type": "enabled"}, "x": 1}),
    )
    assert config.extra_body == {
        "thinking": {"type": "enabled"},
        "reasoning": {"effort": "low"},
        "x": 1,
    }


def test_fill_unset_maps_output_config_effort():
    config = fill_unset(
        {"output_config": {"effort": "high"}, "reasoning_effort": "high"},
        GenerateConfig(),
    )
    assert config.effort == "high"
    assert config.reasoning_effort == "high"
    assert config.extra_body is None


def test_fill_unset_does_not_mutate_inputs():
    mirrored = {"thinking": {"type": "enabled"}, "extra_body": {"a": 1}}
    explicit = GenerateConfig(extra_body={"b": 2})
    fill_unset(mirrored, explicit)
    assert mirrored == {"thinking": {"type": "enabled"}, "extra_body": {"a": 1}}
    assert explicit.extra_body == {"b": 2}


def test_fill_unset_rejects_unknown_native_setting():
    with pytest.raises(ValueError):
        fill_unset({"top_logprobs_v2": 1}, GenerateConfig())


