def _openai_model(tool_calls: list[tuple[str, str, str]]):
    """openai/gpt-5-mini over a mock transport returning one Chat Completion."""
    requests: list[dict] = []

    def handler(request: httpx.Request) -> httpx.Response:
        requests.append(json.loads(request.content))
        return httpx.Response(200, json={
            "id": "chatcmpl-1",
            "object": "chat.completion",
            "created": 0,
            "model": "gpt-5-mini",
            "choices": [{
                "index": 0,
                "finish_reason": "tool_calls",
                "message": {
                    "role": "assistant",
                    "content": None,
                    "tool_calls": [
                        {"id": call_id, "type": "function",
                         "function": {"name": name, "arguments": arguments}}
                        for call_id, name, arguments in tool_calls
                    ],
                },
            }],
            "usage": {"prompt_tokens": 1, "completion_tokens": 1, "total_tokens": 2},
        })

    model = get_model(
        "openai/gpt-5-mini",
        api_key="test-key",
        responses_api=False,
        http_client=httpx.AsyncClient(transport=httpx.MockTransport(handler)),
        memoize=False,
    )
    return model, requests


async def _respond_once(model) -> AgentResponse:
    agent = _agent(model)
    agent.add_user_message("Nothing fits.")
    with active(model):
        return await agent.respond(None)


@pytest.mark.parametrize("raw", ["", "null", "m123", '{"item_id": "m1"}"', "[]"])
async def test_raw_non_object_arguments_raise(raw):
    model, requests = _openai_model([("call_1", "recommend", raw)])
    with pytest.raises(AgentCallError) as info:
        await _respond_once(model)
    assert len(requests) == 1
    assert info.value.function == "recommend"
    assert info.value.tool_call_id == "call_1"
    if raw:
        assert raw not in str(info.value)


async def test_raw_empty_object_is_an_abstention():
    model, _ = _openai_model([("call_1", "recommend", "{}")])
    response = await _respond_once(model)
    assert response.tool_calls == [{"id": "call_1", "name": "recommend", "arguments": {}}]


async def test_raw_arguments_are_json_loads_result():
    model, _ = _openai_model([
        ("call_1", "get_metadata", '{"item_id": "m1"}'),
        ("call_2", "recommend", '{"item_id": null}'),
    ])
    response = await _respond_once(model)
    assert response.tool_calls == [
        {"id": "call_1", "name": "get_metadata", "arguments": {"item_id": "m1"}},
        {"id": "call_2", "name": "recommend", "arguments": {"item_id": None}},
    ]


async def test_raw_capture_sees_every_call_past_transcript_limit():
    # Inspect's transcript keeps ModelEvent.call for only the first 5 calls
    # per model by default; the capture must not depend on it.
    model, requests = _openai_model([("call_1", "recommend", "")])
    agent = _agent(model)
    with active(model):
        for _ in range(7):
            agent.reset()
            agent.add_user_message("Nothing fits.")
            with pytest.raises(AgentCallError):
                await agent.respond(None)
    assert len(requests) == 7


async def test_no_raw_response_falls_back_to_inspect_arguments():
    # mockllm records no OpenAI-shaped response: Inspect's parsed arguments
    # pass through (documented deviation).
    model = _model(Recorder([_tool_output([("c1", "recommend", {"item_id": "m1"})])]))
    response = await _respond_once(model)
    assert response.tool_calls == [
        {"id": "c1", "name": "recommend", "arguments": {"item_id": "m1"}}
    ]


# Provider errors keep request text out (controller ruling 1, Task 8) ---------

# Inspect's ModelGenerateError message embeds the request JSON; this request
# mentions "context length", which the orchestrator matches as a context stop.
AGENT_REQUEST_TEXT = "REQUEST-TEXT a film about the context length of memory"


class _Raises:
    """A mockllm custom_outputs callable that raises ``error`` on every call."""

    def __init__(self, error: BaseException):
        self.error = error
        self.calls = 0

    def __call__(self, input, tools, tool_choice, config):
        self.calls += 1
        raise self.error


def _agent_generate_error(status_code: int | None, cause: Exception | None = None):
    from inspect_ai.model._model import ModelGenerateError

    error = ModelGenerateError(
        f"\nRequest:\n{AGENT_REQUEST_TEXT}\n\nBadRequestError('{AGENT_REQUEST_TEXT}')",
        status_code=status_code,
        # Inspect sets provider_message to str(provider exception): provider
        # text, here with no context-length wording.
        provider_message="provider says the request is invalid",
    )
    error.__cause__ = cause
    return error


@pytest.mark.parametrize("harness", [LEGACY, BOOKS_V4], ids=lambda h: h.id)
async def test_provider_error_with_context_length_request_is_not_a_context_stop(harness):
    from inspect_ai.model._model import ModelGenerateError

    from tau_rec.inspect_support.agent import AgentProviderError

    model = get_model("mockllm/model", custom_outputs=_Raises(_agent_generate_error(400)), memoize=False)
    agent = InspectAgent(model, SYSTEM_PROMPT, TOOL_DEFINITIONS, harness=harness)
    agent.add_user_message("Hi.")
    orchestrator = Orchestrator(agent, simulator=None, toolkit=None, harness=harness)
    with active(model), pytest.raises(AgentProviderError) as info:
        await orchestrator._respond(None)
    assert not isinstance(info.value, _Stop)
    assert str(info.value) == "agent provider call failed (status 400)"
    assert "REQUEST-TEXT" not in str(info.value)
    assert info.value.status_code == 400
    assert info.value.provider_message == "provider says the request is invalid"
    assert isinstance(info.value.__cause__, ModelGenerateError)


async def test_statusless_provider_error_keeps_only_cause_class_name():
    from tau_rec.inspect_support.agent import AgentProviderError

    class APIConnectionError(Exception):
        pass

    error = _agent_generate_error(None, APIConnectionError(AGENT_REQUEST_TEXT))
    model = get_model("mockllm/model", custom_outputs=_Raises(error), memoize=False)
    agent = _agent(model)
    agent.add_user_message("Hi.")
    with active(model), pytest.raises(AgentProviderError) as info:
        await agent.respond(None)
    assert str(info.value) == "agent provider call failed (APIConnectionError)"


async def test_refusal_error_raised_without_model_text():
    from inspect_ai.model._model import ModelRefusalError

    refusal = ModelOutput.from_content(
        "mockllm/model", f"MODEL-TEXT {AGENT_REQUEST_TEXT}", stop_reason="content_filter"
    )
    model = get_model(
        "mockllm/model",
        custom_outputs=_Raises(ModelRefusalError(refusal, "mockllm/model")),
        memoize=False,
    )
    agent = _agent(model)
    agent.add_user_message("Hi.")
    orchestrator = Orchestrator(agent, simulator=None, toolkit=None)
    with active(model), pytest.raises(AgentCallError) as info:
        await orchestrator._respond(None)
    assert "MODEL-TEXT" not in str(info.value)
    assert "REQUEST-TEXT" not in str(info.value)
    assert isinstance(info.value.__cause__, ModelRefusalError)


# Context overflow from providers Inspect does not map (final review, finding 3)

OPENROUTER_CONTEXT_TEXT = (
    "This endpoint's maximum context length is 163840 tokens. However, you requested "
    "about 170000 tokens (169000 of text input, 1000 in the output). Please reduce the "
    'length of either one, or use the "middle-out" transform to compress your prompt '
    "automatically."
)


def _openrouter_400(message: str):
    """openrouter/deepseek/deepseek-v4-flash over a mock transport answering HTTP 400.

    Inspect maps only some providers' context errors to stop_reason
    "model_length"; OpenRouter's 400 reaches the adapter as ModelGenerateError.
    """
    requests: list[dict] = []

    def handler(request: httpx.Request) -> httpx.Response:
        requests.append(json.loads(request.content))
        return httpx.Response(400, json={"error": {"message": message, "code": 400}})

    model = get_model(
        "openrouter/deepseek/deepseek-v4-flash",
        api_key="test-key",
        http_client=httpx.AsyncClient(transport=httpx.MockTransport(handler)),
        memoize=False,
    )
    return model, requests


@pytest.mark.parametrize(
    ("harness", "recorded"),
    [(LEGACY, "timeout"), (BOOKS_V4, "context_overflow")],
    ids=["legacy", "books-v4"],
)
async def test_openrouter_context_400_is_a_context_stop(harness, recorded):
    from inspect_ai.model._model import ModelGenerateError

    model, requests = _openrouter_400(OPENROUTER_CONTEXT_TEXT)
    agent = InspectAgent(model, SYSTEM_PROMPT, TOOL_DEFINITIONS, harness=harness)
    agent.add_user_message("Hi.")
    orchestrator = Orchestrator(agent, simulator=None, toolkit=None, harness=harness)
    with active(model), pytest.raises(_Stop) as info:
        await orchestrator._respond(None)
    assert len(requests) == 1
    cause = info.value.__cause__
    assert isinstance(cause, AgentContextLengthError)
    # Fixed text: the provider message stays on the chained ModelGenerateError.
    assert "163840" not in str(cause)
    assert isinstance(cause.__cause__, ModelGenerateError)
    assert orchestrator._reason(info.value.reason).value == recorded


async def test_openrouter_non_context_400_is_a_provider_error():
    from tau_rec.inspect_support.agent import AgentProviderError

    model, _ = _openrouter_400("deepseek/deepseek-v4-flash is not a valid model ID")
    agent = _agent(model)
    agent.add_user_message("Hi.")
    orchestrator = Orchestrator(agent, simulator=None, toolkit=None)
    with active(model), pytest.raises(AgentProviderError) as info:
        await orchestrator._respond(None)
    assert not isinstance(info.value, _Stop)
    assert str(info.value) == "agent provider call failed (status 400)"


@pytest.mark.parametrize("message", [None, "", "maximum length exceeded", "bad context"])
async def test_provider_message_needs_context_and_length(message):
    from inspect_ai.model._model import ModelGenerateError

    from tau_rec.inspect_support.agent import AgentProviderError

    error = ModelGenerateError(
        f"\nRequest:\n{AGENT_REQUEST_TEXT}", status_code=400, provider_message=message
    )
    model = get_model("mockllm/model", custom_outputs=_Raises(error), memoize=False)
    agent = _agent(model)
    agent.add_user_message("Hi.")
    orchestrator = Orchestrator(agent, simulator=None, toolkit=None)
    with active(model), pytest.raises(AgentProviderError):
        await orchestrator._respond(None)
